<script setup lang="ts">
import {computed,nextTick,onMounted,ref} from 'vue';
import {usePageRoute,usePageMemory,useNavigationGuard,routeId,routeTab,routeText} from './navigation';
import AttendancePage from './AttendancePage.vue';
import VisitQrPoints from './VisitQrPoints.vue';
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>;can:(permission:string)=>boolean}>();
const emit=defineEmits<{reader:[id:number]}>();
const items=ref<any[]>([]),total=ref(0),participants=ref(0),offset=ref(0),busy=ref(false),error=ref(''),branches=ref<any[]>([]),formats=ref<string[]>([]),statuses=ref<Record<string,string>>({});
const filters=ref({q:'',date_from:'',date_to:'',branch_id:'',status:''}),applied=ref({...filters.value});
const selected=ref<any>(null),editor=ref<any>(null),dialog=ref<HTMLDialogElement|null>(null),saving=ref(false),formError=ref('');
const code=ref(''),scanBusy=ref(false),receipt=ref<any>(null),reportVersion=ref(0),exporting=ref(false);
function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Almaty'}).format(new Date());}
function query(){const q=new URLSearchParams();for(const [k,v] of Object.entries(applied.value))if(v)q.set(k,String(v));return q;}
async function load(reset=false){
 if(busy.value)return;busy.value=true;error.value='';
 if(reset){offset.value=0;applied.value={...filters.value};}
 try{const q=query();q.set('offset',String(offset.value));const r=await props.api('/events?'+q);items.value=r.items;total.value=r.total;participants.value=r.participants;}catch(e){error.value=String(e);}finally{busy.value=false;}
}
async function loadOptions(){const r=await props.api('/events/options');branches.value=r.branches;formats.value=r.formats;statuses.value=r.statuses;}
async function open(item:any,restoring=false){if(!restoring&&navigation.go({event:item.id}))return;error.value='';receipt.value=null;try{selected.value=await props.api('/events/'+item.id);reportVersion.value++;window.scrollTo(0,0);}catch(e){error.value=String(e);}}
async function edit(item?:any){
 formError.value='';error.value='';
 try{editor.value=item?await props.api('/events/'+item.id):{title:'',date_from:today(),date_to:today(),format:'',branch_id:branches.value.find(b=>b.active)?.id||null,location:'',responsible:'',coorganizers:'',protocol:false,protocol_url:'',instagram_url:'',notes:'',status:'planned'};await nextTick();dialog.value?.showModal();}catch(e){error.value=String(e);}
}
function closeEditor(){if(saving.value)return;dialog.value?.close();editor.value=null;}
async function save(){
 if(!editor.value||saving.value)return;saving.value=true;formError.value='';
 const fields=['title','date_from','date_to','format','branch_id','location','responsible','coorganizers','protocol','protocol_url','instagram_url','notes','status'];
 const body=Object.fromEntries(fields.map(k=>[k,editor.value[k]]));const id=editor.value.id;if(id)body.version=editor.value.version;
 try{const r=await props.api('/events'+(id?'/'+id:''),id?'PUT':'POST',body);if(!id||selected.value?.id===id){selected.value=r;reportVersion.value++;}dialog.value?.close();editor.value=null;if(selected.value)navigation.go({event:selected.value.id},true);await load();await loadOptions();}catch(e){formError.value=String(e);}finally{saving.value=false;}
}
async function remove(item:any){
 if(!confirm('Удалить мероприятие «'+item.title+'»? Оно исчезнет из списка, QR перестанет работать. Сохранённые отметки останутся в истории базы.'))return;
 error.value='';try{await props.api('/events/'+item.id+'?version='+item.version,'DELETE');if(selected.value?.id===item.id){selected.value=null;navigation.go({},true);}await load();}catch(e){error.value=String(e);}
}
async function scan(){
 if(scanBusy.value)return;scanBusy.value=true;error.value='';receipt.value=null;
 try{receipt.value=await props.api('/events/'+selected.value.id+'/attendance','POST',{code:code.value});code.value='';selected.value=await props.api('/events/'+selected.value.id);reportVersion.value++;}catch(e){error.value=String(e);}finally{scanBusy.value=false;}
}
async function download(){
 if(exporting.value)return;exporting.value=true;error.value='';try{const response=await fetch('/api/events/export?'+query(),{credentials:'same-origin'});if(!response.ok)throw Error('Не удалось выгрузить мероприятия');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='Мероприятия.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=String(e);}finally{exporting.value=false;}
}
const groups=computed(()=>{const result:{key:string;label:string;items:any[]}[]=[];for(const item of items.value){const key=item.date_from.slice(0,7);let g=result.find(g=>g.key===key);if(!g){g={key,label:new Date(key+'-01T12:00:00Z').toLocaleDateString('ru-RU',{month:'long',year:'numeric'}),items:[]};result.push(g);}g.items.push(item);}return result;});
const day=(s:string)=>s.split('-').reverse().join('.');
function page(delta:number){offset.value+=delta;load();window.scrollTo(0,0);}
usePageMemory('events',{filters,applied,offset});
const navigation=usePageRoute('events',async q=>{dialog.value?.close();editor.value=null;const id=routeId(q,'event');if(id){if(selected.value?.id!==id)await open({id},true);}else selected.value=null;},async()=>{try{await loadOptions();await load();}catch(e){error.value=String(e);}});
useNavigationGuard('events',()=>!!editor.value,()=>saving.value||scanBusy.value);
function backToEvents(){if(navigation.go())return;selected.value=null;void load();}

</script>
<template>
<section class="events-page">
 <header class="page-heading">
  <div><h1>{{selected?selected.title:'Мероприятия'}}</h1><p>{{selected?'Карточка мероприятия и отдельный учёт участников.':'План мероприятий, ответственные и посещаемость. У каждого мероприятия — свой QR-код.'}}</p></div>
  <div class="actions" v-if="selected"><button @click="backToEvents">← К списку</button><button v-if="can('events.manage')" @click="edit(selected)">Редактировать</button><VisitQrPoints v-if="can('events.manage')" :key="selected.id" :api="api" :branches="branches" :event-id="selected.id" /></div>
  <div class="actions" v-else><button :disabled="busy||exporting" @click="download">↓ Excel</button><button v-if="can('events.manage')" class="primary" @click="edit()">＋ Создать мероприятие</button></div>
 </header>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <template v-if="selected">
  <article class="card event-detail">
   <dl><div><dt>Дата проведения · Алматы</dt><dd>{{day(selected.date_from)}}{{selected.date_to!==selected.date_from?' — '+day(selected.date_to):''}}</dd></div><div><dt>Формат</dt><dd>{{selected.format||'Не указан'}}</dd></div><div><dt>Пункт обслуживания / место</dt><dd>{{selected.branch}}{{selected.location?' · '+selected.location:''}}</dd></div><div><dt>Статус</dt><dd>{{statuses[selected.status]}}</dd></div><div><dt>Ответственный</dt><dd>{{selected.responsible||'Не указан'}}</dd></div><div><dt>Соорганизаторы</dt><dd>{{selected.coorganizers||'Не указаны'}}</dd></div><div><dt>Протокол</dt><dd>{{selected.protocol?'Есть':'Нет'}} <a v-if="selected.protocol_url" :href="selected.protocol_url" target="_blank" rel="noopener noreferrer">Открыть ↗</a></dd></div><div><dt>Instagram</dt><dd><a v-if="selected.instagram_url" :href="selected.instagram_url" target="_blank" rel="noopener noreferrer">Открыть публикацию ↗</a><span v-else>Не указан</span></dd></div></dl>
   <p v-if="selected.notes" class="notes">{{selected.notes}}</p><p class="muted">Участие отмечается в даты проведения (00:00–23:59, Алматы), пока статус «Запланировано». После завершения журнал и отчёты доступны.</p>
  </article>
  <form v-if="can('events.record')" class="card event-scan" @submit.prevent="scan"><h2>Отметить участника по читательскому билету</h2><div class="actions"><label>Штрихкод или номер билета<input v-model="code" required maxlength="100" placeholder="Отсканируйте или введите билет" :disabled="scanBusy||!selected.can_check_in"></label><button class="primary" :disabled="scanBusy||!selected.can_check_in">{{scanBusy?'Сохраняем…':'Отметить участие'}}</button></div><p v-if="!selected.can_check_in" class="muted">Сейчас регистрация закрыта: проверьте даты и статус мероприятия.</p><p v-if="receipt" role="status" class="event-receipt">{{receipt.duplicate?'Участие уже учтено':'Участие засчитано'}} · {{receipt.full_name}}</p></form>
  <AttendancePage :key="selected.id+':'+reportVersion" :api="api" :can="can" :api-base="'/events/'+selected.id+'/report'" :date-from="selected.date_from" :date-to="selected.date_to" title="Посещаемость мероприятия" description="Участники, учебные группы, факультеты и источники отметки. Все даты и время — Алматы." @reader="emit('reader',$event)" />
  <button v-if="can('events.manage')" class="delete-event" @click="remove(selected)">Удалить мероприятие</button>
 </template>
 <template v-else>
  <div class="event-metrics"><article class="card"><span>Мероприятий по фильтрам</span><strong>{{total.toLocaleString('ru-RU')}}</strong></article><article class="card"><span>Отметок участия</span><strong>{{participants.toLocaleString('ru-RU')}}</strong><small>Один человек на разных мероприятиях учитывается отдельно</small></article></div>
  <form class="card event-filters" @submit.prevent="load(true)"><label class="wide">Название, формат или ответственный<input v-model="filters.q" maxlength="200"></label><label>Дата с<input v-model="filters.date_from" type="date"></label><label>Дата по<input v-model="filters.date_to" type="date"></label><label>Пункт<select v-model="filters.branch_id"><option value="">Все пункты</option><option v-for="b in branches" :value="String(b.id)" :key="b.id">{{b.name}}</option></select></label><label>Статус<select v-model="filters.status"><option value="">Все статусы</option><option v-for="(name,k) in statuses" :key="k" :value="k">{{name}}</option></select></label><button class="primary" :disabled="busy">Применить</button></form>
  <div class="actions pager"><span>{{total?offset+1:0}}–{{Math.min(offset+50,total)}} из {{total}}</span><button :disabled="busy||offset===0" @click="page(-50)">Назад</button><button :disabled="busy||offset+50>=total" @click="page(50)">Далее</button></div>
  <div class="card event-table"><table><thead><tr><th>№</th><th>Мероприятие</th><th>Дата</th><th>Формат</th><th>Участников</th><th>Протокол</th><th>Instagram</th><th>Ответственный / соорганизаторы</th><th>Примечания</th><th>Действия</th></tr></thead><tbody><template v-for="group in groups" :key="group.key"><tr class="event-month"><th colspan="10">{{group.label}}</th></tr><tr v-for="item in group.items" :key="item.id"><td>{{item.id}}</td><td><button class="event-title" @click="open(item)">{{item.title}}</button><small>{{item.branch}} · {{statuses[item.status]}}</small></td><td>{{day(item.date_from)}}<template v-if="item.date_to!==item.date_from"><br>— {{day(item.date_to)}}</template></td><td>{{item.format||'—'}}</td><td><button @click="open(item)">{{item.participants}}</button></td><td><a v-if="item.protocol_url" :href="item.protocol_url" target="_blank" rel="noopener noreferrer">{{item.protocol?'Есть ↗':'Ссылка ↗'}}</a><span v-else>{{item.protocol?'Есть':'—'}}</span></td><td><a v-if="item.instagram_url" :href="item.instagram_url" target="_blank" rel="noopener noreferrer">Открыть ↗</a><span v-else>—</span></td><td>{{item.responsible||'—'}}<small>{{item.coorganizers}}</small></td><td class="notes">{{item.notes||'—'}}</td><td><button @click="open(item)">Участники и QR</button><button v-if="can('events.manage')" @click="edit(item)">Изменить</button></td></tr></template><tr v-if="!items.length"><td colspan="10" class="empty">{{busy?'Загрузка…':'Мероприятий по этим условиям нет.'}}</td></tr></tbody></table></div>
 </template>
 <dialog ref="dialog" class="event-dialog" aria-labelledby="event-editor-title" @cancel="saving?$event.preventDefault():closeEditor()"><form v-if="editor" @submit.prevent="save"><header class="actions"><h2 id="event-editor-title">{{editor.id?'Изменить мероприятие':'Новое мероприятие'}}</h2><button type="button" :disabled="saving" @click="closeEditor" aria-label="Закрыть">✕</button></header><p v-if="formError" class="error" role="alert">{{formError}}</p><fieldset :disabled="saving"><label>Название мероприятия<input v-model="editor.title" required maxlength="500"></label><div class="form-grid"><label>Дата начала<input v-model="editor.date_from" type="date" required></label><label>Дата окончания<input v-model="editor.date_to" type="date" :min="editor.date_from" required></label><label>Формат<input v-model="editor.format" list="event-formats" maxlength="150" placeholder="Выставка, встреча, фотосессия…"><datalist id="event-formats"><option v-for="f in formats" :key="f" :value="f" /></datalist></label><label>Статус<select v-model="editor.status"><option v-for="(name,k) in statuses" :key="k" :value="k">{{name}}</option></select></label><label>Пункт обслуживания<select v-model="editor.branch_id" required><option :value="null" disabled>Выберите пункт</option><option v-for="b in branches.filter(b=>b.active||b.id===editor.branch_id)" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>Место / аудитория<input v-model="editor.location" maxlength="300"></label><label>Ответственный исполнитель<input v-model="editor.responsible" maxlength="500"></label><label>Совместные исполнители<input v-model="editor.coorganizers" maxlength="500"></label></div><label class="protocol"><input v-model="editor.protocol" type="checkbox"> Протокол оформлен</label><label>Ссылка на протокол<input v-model="editor.protocol_url" type="url" maxlength="2000" placeholder="https://…"></label><label>Ссылка Instagram<input v-model="editor.instagram_url" type="url" maxlength="2000" placeholder="https://www.instagram.com/…"></label><label>Примечания<textarea v-model="editor.notes" rows="3" maxlength="10000"></textarea></label><p class="muted">Количество посетителей рассчитывается по отметкам. Для одного дня укажите одинаковые даты начала и окончания.</p></fieldset><footer class="actions"><button type="button" :disabled="saving" @click="closeEditor">Отмена</button><button class="primary" :disabled="saving">{{saving?'Сохраняем…':'Сохранить'}}</button></footer></form></dialog>
</section>
</template>
<style scoped>
.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.page-heading{gap:24px}.event-metrics{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:24px}.event-metrics article{padding:26px;display:flex;flex-direction:column;gap:10px}.event-metrics strong{font-size:36px;color:#052744}.event-metrics small,.muted,dt{color:#6b7f99;font-size:13px;line-height:1.6}.event-filters{padding:24px;display:flex;gap:16px;flex-wrap:wrap;align-items:end}.event-filters .wide{flex:1;min-width:230px}label{display:flex;flex-direction:column;gap:7px;color:#536579;font-size:14px;font-weight:600}input,select,textarea{width:100%;box-sizing:border-box}.pager{justify-content:flex-end;margin:20px 0}.event-table{padding:0;overflow:auto}.event-table table{width:100%;min-width:1250px}.event-table th,.event-table td{padding:16px;text-align:left;vertical-align:top;border-bottom:1px solid #e3ebf2}.event-table thead,.event-month{background:#eef3f7}.event-month th{text-transform:capitalize;color:#052744}.event-table small{display:block;color:#75869b;font-size:12px;margin-top:8px}.event-table td:nth-child(2){min-width:230px;max-width:350px}.event-title{padding:0;border:0;background:none;text-align:left;color:#087e83;font-weight:700}.event-table td:last-child button{display:block;margin-bottom:8px}.event-detail{padding:28px;margin-bottom:24px}.event-detail dl{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.event-detail dd{margin:6px 0;overflow-wrap:anywhere}.notes{white-space:pre-wrap;overflow-wrap:anywhere;max-width:350px}.event-scan{padding:24px;margin-bottom:28px}.event-scan h2{font-size:20px;margin:0 0 20px}.event-scan label{flex:1}.event-scan .actions{align-items:end}.event-receipt{padding:14px;border-radius:10px;background:#e8f9f0;color:#067855}.delete-event{margin-top:24px;color:#a43d34}.empty{text-align:center!important;padding:48px!important;color:#6b7f99}.event-dialog{width:min(800px,calc(100vw - 32px));box-sizing:border-box;max-height:90vh;overflow:auto;border:1px solid #dae4ed;border-radius:22px;padding:28px;color:#052744}.event-dialog::backdrop{background:#05274488}.event-dialog header{justify-content:space-between}.event-dialog h2{margin:0}.event-dialog fieldset{padding:0;border:0;margin:24px 0}.event-dialog label{margin-bottom:18px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.protocol{flex-direction:row;align-items:center}.protocol input{width:auto}.event-dialog footer{justify-content:flex-end}@media(max-width:900px){.event-detail dl{grid-template-columns:1fr 1fr}.event-metrics{gap:14px}}@media(max-width:580px){.event-metrics,.form-grid,.event-detail dl{grid-template-columns:1fr}.event-filters label{width:100%}.event-dialog{padding:20px}}
</style>
